from collections import Counter,deque
def transform(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; boxes=[]
    for i in range(H):
        for j in range(W):
            if seen[i][j] or g[i][j]==0: continue
            c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; comp=[]
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                        seen[ny][nx]=True; q.append((ny,nx))
            ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
            y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
            area=(y1-y0+1)*(x1-x0+1)
            if len(comp)>=6 and len(comp)/area>=0.8:
                boxes.append((c,y0,y1,x0,x1))
    res=[row[:] for row in g]; inrect=[[False]*W for _ in range(H)]
    for c,y0,y1,x0,x1 in boxes:
        for y in range(y0,y1+1):
            for x in range(x0,x1+1):
                res[y][x]=c; inrect[y][x]=True
    nonrect=Counter(g[i][j] for i in range(H) for j in range(W) if not inrect[i][j])
    bg=nonrect.most_common(1)[0][0]
    for i in range(H):
        for j in range(W):
            if not inrect[i][j]: res[i][j]=bg
    return res

